/**
 * FridgeMama — service worker.
 *
 * Hand-written rather than generated by Workbox, for one reason: adding a
 * build-time PWA plugin means an npm install, and the whole point of this
 * project is that it runs at a venue with the WiFi off. Nothing here needs a
 * dependency, and nothing here needs to know the hashed asset filenames Vite
 * produces — the shell is cached on first load and the rest fills in as it is
 * used.
 *
 * Two strategies, split by what the thing is:
 *
 *   the app itself   cache-first. HTML, JS, CSS, fonts and images never change
 *                    between builds because their names carry a content hash,
 *                    so serving them from disk is both correct and instant.
 *
 *   /api/*           network-only. A fridge is live state — a cached shelf is
 *                    a lie, and showing a judge yesterday's fridge is worse
 *                    than showing them an error. The laptop is two feet away;
 *                    if it cannot be reached, that is worth knowing.
 *
 * Bumping CACHE drops every older cache on activate, so a rebuild during
 * rehearsal cannot leave a stale bundle installed on somebody's phone.
 */

const CACHE = "fridgemama-v1";

// Everything needed to paint the first screen with no network at all. The
// hashed bundles are not listed because their names are unknown here; they are
// picked up by the fetch handler the first time the app loads.
const SHELL = [
  "/",
  "/manifest.webmanifest",
  "/icons/icon-192.png",
  "/icons/icon-512.png",
  "/icons/icon-maskable-512.png",
  "/icons/apple-touch-icon.png",
  "/favicon.ico",
];

self.addEventListener("install", (event) => {
  event.waitUntil(
    caches
      .open(CACHE)
      // One missing file must not fail the whole install, so each is added on
      // its own and allowed to fail quietly.
      .then((cache) => Promise.all(SHELL.map((url) => cache.add(url).catch(() => {}))))
      .then(() => self.skipWaiting())
  );
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((keys) => Promise.all(keys.filter((k) => k !== CACHE).map((k) => caches.delete(k))))
      .then(() => self.clients.claim())
  );
});

// An escape hatch for rehearsal: from the console, a waiting worker can be
// told to take over now rather than on the next cold start.
//   navigator.serviceWorker.getRegistration()
//     .then(r => r.waiting?.postMessage("skip-waiting"))
self.addEventListener("message", (event) => {
  if (event.data === "skip-waiting") self.skipWaiting();
});

self.addEventListener("fetch", (event) => {
  const { request } = event;

  if (request.method !== "GET") return;

  const url = new URL(request.url);

  // Someone else's origin is not ours to cache.
  if (url.origin !== self.location.origin) return;

  // Live state, and the photo upload's sibling routes. Never cached.
  if (url.pathname.startsWith("/api/")) return;

  // A navigation is any address the user can land on. All of them are the same
  // single screen, so any of them is answered with the cached shell — this is
  // what makes the installed app open instantly, and open at all when the
  // laptop is asleep.
  if (request.mode === "navigate") {
    event.respondWith(
      fetch(request)
        .then((response) => {
          const copy = response.clone();
          caches.open(CACHE).then((cache) => cache.put("/", copy));
          return response;
        })
        .catch(() => caches.match("/").then((hit) => hit || offlinePage()))
    );
    return;
  }

  // Everything else: serve from cache if we have it, otherwise fetch it and
  // keep a copy for next time.
  event.respondWith(
    caches.match(request).then(
      (hit) =>
        hit ||
        fetch(request).then((response) => {
          if (response.ok && response.type === "basic") {
            const copy = response.clone();
            caches.open(CACHE).then((cache) => cache.put(request, copy));
          }
          return response;
        })
    )
  );
});

/** Last resort: the app is installed but its shell was never cached. */
function offlinePage() {
  return new Response(
    `<!doctype html><meta charset="utf-8">
     <meta name="viewport" content="width=device-width,initial-scale=1">
     <title>FridgeMama</title>
     <style>
       body{margin:0;display:grid;place-items:center;min-height:100vh;
            background:#f4f7f8;color:#4b5a5e;
            font:500 15px/1.5 system-ui,-apple-system,sans-serif;text-align:center}
       p{margin:.4rem 1.5rem}
       strong{color:#12343b}
     </style>
     <div>
       <p><strong>FridgeMama can&rsquo;t reach the kitchen.</strong></p>
       <p>Start the demo on the laptop, then pull down to reload.</p>
     </div>`,
    { headers: { "Content-Type": "text/html; charset=utf-8" }, status: 503 }
  );
}
